Definition WF (P a : Z) : Prop := P + 160 <= a < P + 184 \/ P + 200 <= a < P + 209.
(* [comment removed for export] *)
Definition CRD (bcap kx bx : Z) (cr : credit) (c : Z) : Prop :=
  0 <= kx /\ 0 <= bx /\
  (bcap <= 2 ^ 27 /\ (Z.log2 (2 ^ 27 / bcap) + Z.log2 (1056 / c)) * hl_k_per_malloc L <= fst cr - kx /\
   hl_b_lin L * ((2 ^ 28 - 2 * bcap) + (2112 - 2 * c)) + (Z.log2 (2 ^ 27 / bcap) + Z.log2 (1056 / c)) * hl_b_overhead L <= snd cr - bx).
